        {"id": "SCORE-WKL", "severity": "major", "status": "responded", "message": "Der Gesamtscore ist zerlegbar, aber die Quellen- und Rubrikbelege je Kategorie sind unvollständig.", "response": "Es wird kein neuer Gesamtscore erfunden.", "resolution_required": "Versionierte Belege je Kategorie und vollständigen Scoreabgleich vorlegen."},
